1	package process
2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"net/http"
8		"os"
9		"os/exec"
10		"os/signal"
11		"syscall"
12		"testing"
13		"time"
14	
15		"github.com/nogo/wire/internal/config"
16	)
17	
18	// ---------------------------------------------------------------------------
19	// Subprocess helper: fake llama-server
20	//
21	// Tests that need a real process invoke the test binary itself with
22	// GO_WANT_HELPER_PROCESS=1 and -test.run=TestHelperProcess.
23	// The subprocess then acts as a minimal llama-server on the requested port.
24	// ---------------------------------------------------------------------------
25	
26	// TestHelperProcess is NOT a real test — it is a subprocess target.
27	func TestHelperProcess(t *testing.T) {
28		if os.Getenv("GO_WANT_HELPER_PROCESS") != "1" {
29			return
30		}
31	
32		// Locate args after "--"
33		args := os.Args
34		for i, a := range args {
35			if a == "--" {
36				args = args[i+1:]
37				break
38			}
39		}
40	
41		if len(args) == 0 || args[0] != "llama-server" {
42			fmt.Fprintln(os.Stderr, "expected llama-server as first arg")
43			os.Exit(2)
44		}
45	
46		// Parse --port from remaining flags.
47		port := "8080"
48		for i, a := range args[1:] {
49			if a == "--port" && i+1 < len(args[1:]) {
50				port = args[1:][i+1]
51			}
52		}
53	
54		mux := http.NewServeMux()
55		mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
56			w.WriteHeader(http.StatusOK)
57		})
58	
59		srv := &http.Server{Addr: ":" + port, Handler: mux}
60		go srv.ListenAndServe() //nolint:errcheck
61	
62		sigCh := make(chan os.Signal, 1)
63		signal.Notify(sigCh, syscall.SIGTERM, syscall.SIGINT)
64		<-sigCh
65	
66		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
67		defer cancel()
68		srv.Shutdown(ctx) //nolint:errcheck
69		os.Exit(0)
70	}
71	
72	// testCmdBuilder returns a cmdBuilder that runs the test binary as a fake
73	// llama-server subprocess.
74	func testCmdBuilder(ctx context.Context, modelName string, params config.ModelParams, port int) *exec.Cmd {
75		args := append(
76			[]string{"-test.run=TestHelperProcess", "--", "llama-server"},
77			buildArgs(modelName, params, port)...,
78		)
79		cmd := exec.CommandContext(ctx, os.Args[0], args...)
80		cmd.Env = append(os.Environ(), "GO_WANT_HELPER_PROCESS=1")
81		return cmd
82	}
83	
84	// newTestManager creates a Manager wired to the fake llama-server subprocess.
85	func newTestManager(cfg *config.Config) *Manager {
86		m := New(cfg, slog.Default())
87		m.cmdBuilder = testCmdBuilder
88		return m
89	}
90	
91	// ---------------------------------------------------------------------------
92	// Unit tests — pure functions
93	// ---------------------------------------------------------------------------
94	
95	func TestBuildArgs_minimal(t *testing.T) {
96		params := config.ModelParams{}
97		got := buildArgs("org/model", params, 19100)
98		want := []string{"-hf", "org/model", "--port", "19100", "--no-webui", "--parallel", "1"}
99		if fmt.Sprint(got) != fmt.Sprint(want) {
100			t.Errorf("buildArgs minimal: got %v, want %v", got, want)
101		}
102	}
103	
104	func TestBuildArgs_full(t *testing.T) {
105		params := config.ModelParams{
106			GPULayers: 32,
107			Context:   4096,
108			Slots:     4,
109			Pooling:   "mean",
110			Extra:     []string{"--flash-attn"},
111		}
112		got := buildArgs("org/model", params, 19101)
113		want := []string{
114			"-hf", "org/model",
115			"--port", "19101",
116			"--no-webui",
117			"--parallel", "4",
118			"-ngl", "32",
119			"-c", "4096",
120			"--embedding", "--pooling", "mean",
121			"--flash-attn",
122		}
123		if fmt.Sprint(got) != fmt.Sprint(want) {
124			t.Errorf("buildArgs full: got %v, want %v", got, want)
125		}
126	}
127	
128	func TestBuildArgs_zeroGPULayersOmitted(t *testing.T) {
129		params := config.ModelParams{GPULayers: 0, Context: 0}
130		args := buildArgs("org/model", params, 19102)
131		for _, a := range args {
132			if a == "-ngl" || a == "-c" {
133				t.Errorf("unexpected flag %q in args: %v", a, args)
134			}
135		}
136	}
137	
138	func TestFreePort(t *testing.T) {
139		port, err := freePort()
140		if err != nil {
141			t.Fatalf("freePort: %v", err)
142		}
143		if port <= 0 || port > 65535 {
144			t.Errorf("freePort returned out-of-range port: %d", port)
145		}
146	}
