148	// ---------------------------------------------------------------------------
149	// Manager tests
150	// ---------------------------------------------------------------------------
151	
152	func TestManager_AddrMissing(t *testing.T) {
153		m := New(&config.Config{}, slog.Default())
154		_, ok := m.Addr("nonexistent")
155		if ok {
156			t.Error("Addr: expected ok=false for missing model")
157		}
158	}
159	
160	func TestManager_HealthyMissing(t *testing.T) {
161		m := New(&config.Config{}, slog.Default())
162		if m.Healthy("nonexistent") {
163			t.Error("Healthy: expected false for unknown model")
164		}
165	}
166	
167	func TestManager_StartStop(t *testing.T) {
168		cfg := &config.Config{
169			Models: map[string]config.ModelParams{
170				"org/test-model": {Slots: 1},
171			},
172			Warmup:    []string{"org/test-model"},
173			MaxModels: 1,
174		}
175		m := newTestManager(cfg)
176	
177		ctx, cancel := context.WithCancel(context.Background())
178		defer cancel()
179	
180		if err := m.Start(ctx); err != nil {
181			t.Fatalf("Start: %v", err)
182		}
183	
184		// Poll until healthy (up to 10s for the subprocess to spin up).
185		deadline := time.Now().Add(10 * time.Second)
186		for time.Now().Before(deadline) {
187			if m.Healthy("org/test-model") {
188				break
189			}
190			time.Sleep(100 * time.Millisecond)
191		}
192	
193		if !m.Healthy("org/test-model") {
194			t.Fatal("model did not become healthy within 10s")
195		}
196	
197		addr, ok := m.Addr("org/test-model")
198		if !ok {
199			t.Fatal("Addr: expected ok=true after healthy")
200		}
201		if addr == "" {
202			t.Error("Addr: returned empty string")
203		}
204	
205		running := m.RunningModels()
206		if len(running) != 1 || running[0] != "org/test-model" {
207			t.Errorf("RunningModels: got %v, want [org/test-model]", running)
208		}
209	
210		if err := m.Stop(); err != nil {
211			t.Errorf("Stop: %v", err)
212		}
213	
214		if m.Healthy("org/test-model") {
215			t.Error("Healthy: expected false after Stop")
216		}
217	}
