1	package gateway
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"io"
8		"log/slog"
9		"net/http"
10		"net/http/httputil"
11		"net/url"
12		"time"
13	
14		"github.com/nogo/wire/internal/config"
15		"github.com/nogo/wire/internal/monitor"
16		"github.com/nogo/wire/internal/process"
17	)
18	
19	// backendManager is the subset of process.Manager the Gateway depends on.
20	type backendManager interface {
21		Addr(name string) (string, bool)
22		Healthy(name string) bool
23		RunningModels() []string
24	}
25	
26	// Gateway is an HTTP reverse-proxy that routes OpenAI-compatible requests to llama-server processes.
27	type Gateway struct {
28		cfg      *config.Config
29		mgr      backendManager
30		log      *slog.Logger
31		affinity *affinityTable
32		server   *http.Server
33	}
34	
35	// New creates a Gateway backed by the given process manager.
36	// hub may be nil; when non-nil, /monitor and /monitor/ws routes are registered.
37	func New(cfg *config.Config, mgr *process.Manager, hub *monitor.Hub, log *slog.Logger) *Gateway {
38		return newGateway(cfg, mgr, hub, log)
39	}
40	
41	func newGateway(cfg *config.Config, mgr backendManager, hub *monitor.Hub, log *slog.Logger) *Gateway {
42		// Build affinity table from warmup models.
43		modelSlots := make(map[string]int, len(cfg.Warmup))
44		for _, name := range cfg.Warmup {
45			if params, ok := cfg.MatchModel(name); ok {
46				modelSlots[name] = params.Slots
47			}
48		}
49	
50		g := &Gateway{cfg: cfg, mgr: mgr, log: log, affinity: newAffinityTable(modelSlots)}
51	
52		mux := http.NewServeMux()
53		mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
54		mux.HandleFunc("POST /v1/completions", g.handleRoute)
55		mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
56		mux.HandleFunc("POST /v1/rerank", g.handleRoute)
57		mux.HandleFunc("GET /v1/models", g.handleModels)
58		mux.HandleFunc("GET /health", g.handleHealth)
59	
60		if hub != nil {
61			mux.HandleFunc("GET /monitor", monitor.HandlePage)
62			mux.HandleFunc("GET /monitor/ws", monitor.HandleWS(hub))
63		}
64	
65		g.server = &http.Server{Addr: cfg.Listen, Handler: mux}
66		return g
67	}
68	
69	// ListenAndServe starts the HTTP server and shuts it down when ctx is cancelled.
70	func (g *Gateway) ListenAndServe(ctx context.Context) error {
71		errCh := make(chan error, 1)
72		go func() {
73			if err := g.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
74				errCh <- err
75			}
76		}()
77		select {
78		case err := <-errCh:
79			return err
80		case <-ctx.Done():
81			shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
82			defer cancel()
83			return g.server.Shutdown(shutCtx)
84		}
85	}
86	
87	// handleRoute extracts the model field from the JSON body and proxies to the matching process.
88	func (g *Gateway) handleRoute(w http.ResponseWriter, r *http.Request) {
89		// Tee the body so the decoder and the upstream both see it.
90		var captured bytes.Buffer
91		tee := io.TeeReader(r.Body, &captured)
92		dec := json.NewDecoder(tee)
93	
94		var payload struct {
95			Model string `json:"model"`
96		}
97		if err := dec.Decode(&payload); err != nil {
98			writeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON: "+err.Error(), "bad_request")
99			return
100		}
101		if payload.Model == "" {
102			writeError(w, http.StatusBadRequest, "invalid_request_error", "missing model field", "bad_request")
103			return
104		}
105	
106		// Reconstruct full body: captured bytes (read by decoder) + rest not yet read.
107		r.Body = io.NopCloser(io.MultiReader(&captured, r.Body))
108	
109		if _, ok := g.cfg.MatchModel(payload.Model); !ok {
110			writeError(w, http.StatusNotFound, "invalid_request_error", "unknown model: "+payload.Model, "model_not_found")
111			return
112		}
113	
114		if !g.mgr.Healthy(payload.Model) {
115			writeError(w, http.StatusServiceUnavailable, "server_error", "model not loaded", "model_not_loaded")
116			return
117		}
118	
119		addr, ok := g.mgr.Addr(payload.Model)
120		if !ok {
121			writeError(w, http.StatusServiceUnavailable, "server_error", "model not loaded", "model_not_loaded")
122			return
123		}
124	
125		// Slot affinity: read full body, compute prefix hash, inject id_slot if assigned.
126		// On any error, fall through with the original body unchanged.
127		if allBody, readErr := io.ReadAll(r.Body); readErr == nil {
128			hash := prefixHash(allBody)
129			if slotID, assigned := g.affinity.Assign(payload.Model, hash); assigned {
130				allBody = injectSlot(allBody, slotID)
131			}
132			r.Body = io.NopCloser(bytes.NewReader(allBody))
133			r.ContentLength = int64(len(allBody))
134		}
135	
136		target, parseErr := url.Parse(addr)
137		if parseErr != nil {
138			writeError(w, http.StatusInternalServerError, "server_error", "invalid backend URL", "internal_error")
139			return
140		}
141	
142		proxy := &httputil.ReverseProxy{
143			Rewrite: func(pr *httputil.ProxyRequest) {
144				pr.SetURL(target)
145				pr.Out.Host = target.Host
146			},
147			FlushInterval: -1,
148			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
149				g.log.Error("proxy error", "model", payload.Model, "error", err)
150				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
151			},
152		}
153	
154		proxy.ServeHTTP(w, r)
155	}
156	
157	// handleModels returns the list of currently running models.
158	func (g *Gateway) handleModels(w http.ResponseWriter, _ *http.Request) {
159		type modelObj struct {
160			ID      string `json:"id"`
161			Object  string `json:"object"`
162			OwnedBy string `json:"owned_by"`
163		}
164		type modelsResp struct {
165			Object string     `json:"object"`
166			Data   []modelObj `json:"data"`
167		}
168	
169		running := g.mgr.RunningModels()
170		data := make([]modelObj, len(running))
171		for i, name := range running {
172			data[i] = modelObj{ID: name, Object: "model", OwnedBy: "wire"}
173		}
174	
175		w.Header().Set("Content-Type", "application/json")
176		json.NewEncoder(w).Encode(modelsResp{Object: "list", Data: data}) //nolint:errcheck
177	}
178	
179	// handleHealth returns 200 if at least one warmup model is healthy, 503 otherwise.
180	func (g *Gateway) handleHealth(w http.ResponseWriter, _ *http.Request) {
181		w.Header().Set("Content-Type", "application/json")
182		for _, name := range g.cfg.Warmup {
183			if g.mgr.Healthy(name) {
184				w.WriteHeader(http.StatusOK)
185				json.NewEncoder(w).Encode(map[string]string{"status": "ok"}) //nolint:errcheck
186				return
187			}
188		}
189		w.WriteHeader(http.StatusServiceUnavailable)
190		json.NewEncoder(w).Encode(map[string]string{"status": "degraded"}) //nolint:errcheck
191	}
192	
193	// writeError writes an OpenAI-format JSON error response.
194	func writeError(w http.ResponseWriter, status int, errType, message, code string) {
195		w.Header().Set("Content-Type", "application/json")
196		w.WriteHeader(status)
197		json.NewEncoder(w).Encode(map[string]any{ //nolint:errcheck
198			"error": map[string]any{
199				"message": message,
200				"type":    errType,
201				"code":    code,
202			},
203		})
204	}
205	
