1	package gateway
2	
3	import (
4		"encoding/json"
5		"hash/fnv"
6		"strconv"
7		"sync"
8	)
9	
10	// affinityTable maps prefix hashes to slot IDs per model, enabling KV cache
11	// reuse in llama-server by routing requests with matching prefixes to the same slot.
12	type affinityTable struct {
13		mu     sync.Mutex
14		models map[string]*backendSlots
15	}
16	
17	type backendSlots struct {
18		slotCount   int
19		assignments map[uint64]int // prefix hash → slot ID
20		lru         []uint64       // eviction order, oldest first
21	}
22	
23	// newAffinityTable creates an affinity table from a map of model name → slot count.
24	func newAffinityTable(models map[string]int) *affinityTable {
25		at := &affinityTable{models: make(map[string]*backendSlots, len(models))}
26		for name, slots := range models {
27			if slots <= 0 {
28				slots = 1
29			}
30			at.models[name] = &backendSlots{
31				slotCount:   slots,
32				assignments: make(map[uint64]int),
33			}
34		}
35		return at
36	}
37	
38	// Assign returns the slot ID to use for a request with the given prefix hash on
39	// the named model. Returns (-1, false) when hash is 0 or the model is unknown.
40	func (at *affinityTable) Assign(model string, hash uint64) (int, bool) {
41		if hash == 0 {
42			return -1, false
43		}
44	
45		at.mu.Lock()
46		defer at.mu.Unlock()
47	
48		bs, ok := at.models[model]
49		if !ok {
50			return -1, false
51		}
52	
53		// Single-slot models always use slot 0; no table needed.
54		if bs.slotCount == 1 {
55			return 0, true
56		}
57	
58		// Existing assignment: refresh LRU position.
59		if slotID, exists := bs.assignments[hash]; exists {
60			for i, h := range bs.lru {
61				if h == hash {
62					bs.lru = append(bs.lru[:i], bs.lru[i+1:]...)
63					break
64				}
65			}
66			bs.lru = append(bs.lru, hash)
67			return slotID, true
68		}
69	
70		// Free slot available: assign the next unused slot ID.
71		if len(bs.assignments) < bs.slotCount {
72			used := make(map[int]bool, len(bs.assignments))
73			for _, s := range bs.assignments {
74				used[s] = true
75			}
76			for i := range bs.slotCount {
77				if !used[i] {
78					bs.assignments[hash] = i
79					bs.lru = append(bs.lru, hash)
80					return i, true
81				}
82			}
83		}
84	
85		// All slots assigned: evict the oldest LRU entry and reuse its slot.
86		oldest := bs.lru[0]
87		slotID := bs.assignments[oldest]
88		bs.lru = bs.lru[1:]
89		delete(bs.assignments, oldest)
90		bs.assignments[hash] = slotID
91		bs.lru = append(bs.lru, hash)
92		return slotID, true
93	}
94	
95	// prefixHash returns a 64-bit FNV-1a hash of the dominant stable prefix in the
96	// request: the system message content, falling back to the first user message.
97	// Returns 0 on parse error or when no usable prefix is found.
98	func prefixHash(body []byte) uint64 {
99		var payload struct {
100			Messages []struct {
101				Role    string `json:"role"`
102				Content string `json:"content"`
103			} `json:"messages"`
104		}
105		if err := json.Unmarshal(body, &payload); err != nil {
106			return 0
107		}
108	
109		var text string
110		for _, m := range payload.Messages {
111			if m.Role == "system" {
112				text = m.Content
113				break
114			}
115		}
116		if text == "" {
117			for _, m := range payload.Messages {
118				if m.Role == "user" {
119					text = m.Content
120					break
121				}
122			}
123		}
124		if text == "" {
125			return 0
126		}
127	
128		h := fnv.New64a()
129		h.Write([]byte(text)) //nolint:errcheck
130		return h.Sum64()
131	}
132	
133	// injectSlot inserts `"id_slot":N,` immediately after the opening brace of a
134	// JSON object body. The body must be a valid JSON object (guaranteed by the
135	// model extraction that precedes this call).
136	func injectSlot(body []byte, slotID int) []byte {
137		for i, b := range body {
138			if b == '{' {
139				field := `"id_slot":` + strconv.Itoa(slotID) + `,`
140				result := make([]byte, 0, len(body)+len(field))
141				result = append(result, body[:i+1]...)
142				result = append(result, field...)
143				result = append(result, body[i+1:]...)
144				return result
145			}
146		}
147		return body
148	}
