16	// ---- prefixHash tests -------------------------------------------------------
17	
18	func TestPrefixHash_Stability(t *testing.T) {
19		body := `{"model":"m","messages":[{"role":"system","content":"You are helpful."},{"role":"user","content":"Hi"}]}`
20		h1 := prefixHash([]byte(body))
21		h2 := prefixHash([]byte(body))
22		if h1 == 0 {
23			t.Fatal("expected non-zero hash for valid system message")
24		}
25		if h1 != h2 {
26			t.Errorf("hash not stable: %d != %d", h1, h2)
27		}
28	}
29	
30	func TestPrefixHash_DifferentSystemPrompts(t *testing.T) {
31		body1 := `{"model":"m","messages":[{"role":"system","content":"You are a coder."}]}`
32		body2 := `{"model":"m","messages":[{"role":"system","content":"You are a chef."}]}`
33		if prefixHash([]byte(body1)) == prefixHash([]byte(body2)) {
34			t.Error("different system prompts should produce different hashes")
35		}
36	}
37	
38	func TestPrefixHash_FallbackToFirstUser(t *testing.T) {
39		body := `{"model":"m","messages":[{"role":"user","content":"Hello, world!"}]}`
40		h := prefixHash([]byte(body))
41		if h == 0 {
42			t.Error("expected non-zero hash using first user message as fallback")
43		}
44	}
45	
46	func TestPrefixHash_EmptyMessages(t *testing.T) {
47		body := `{"model":"m","messages":[]}`
48		if h := prefixHash([]byte(body)); h != 0 {
49			t.Errorf("empty messages should return 0, got %d", h)
50		}
51	}
52	
53	func TestPrefixHash_ParseError(t *testing.T) {
