55			t.Errorf("parse error should return 0, got %d", h)
56		}
57	}
58	
59	func TestPrefixHash_NoMessages(t *testing.T) {
60		if h := prefixHash([]byte(`{"model":"m"}`)); h != 0 {
61			t.Errorf("missing messages should return 0, got %d", h)
62		}
