34	}
35	
36	type ModelParams struct {
37		Context   int      `yaml:"context"`
38		GPULayers int      `yaml:"gpu_layers"`
39		Slots     int      `yaml:"slots"`
40		Pooling   string   `yaml:"pooling"`
41		Extra     []string `yaml:"extra"`
42	}
43	
44	// MatchModel returns the ModelParams for the first glob pattern in Models that
45	// matches name. Returns zero ModelParams and false if no pattern matches.
46	func (c *Config) MatchModel(name string) (ModelParams, bool) {
47		for pattern, params := range c.Models {
48			matched, err := filepath.Match(pattern, name)
49			if err == nil && matched {
50				return params, true
51			}
52		}
53		return ModelParams{}, false
54	}
55	
56	// Load reads the config from disk, applies defaults, and validates it.
57	func Load() (*Config, error) {
58		path := Path()
59	
60		data, err := os.ReadFile(path)
61		if err != nil {
62			if errors.Is(err, os.ErrNotExist) {
63				return nil, fmt.Errorf("config file not found at %s: %w", path, err)
64			}
65			return nil, fmt.Errorf("reading config %s: %w", path, err)
66		}
67	
68		cfg := new(Config)
69		dec := yaml.NewDecoder(bytes.NewReader(data))
70		dec.KnownFields(true)
71		if err := dec.Decode(cfg); err != nil {
72			return nil, fmt.Errorf("parsing config %s: %w", path, err)
73		}
74	
75		applyDefaults(cfg)
76	
77		if err := validate(cfg); err != nil {
78			return nil, err
79		}
80	
81		return cfg, nil
82	}
83	
84	func applyDefaults(cfg *Config) {
85		if cfg.Listen == "" {
86			cfg.Listen = ":9480"
87		}
88		if cfg.MaxModels == 0 {
89			cfg.MaxModels = 1
90		}
91		for pattern, p := range cfg.Models {
92			if p.Slots == 0 {
93				p.Slots = 1
94				cfg.Models[pattern] = p
95			}
96		}
97	}
98	
99	func validate(cfg *Config) error {
100		for _, entry := range cfg.Warmup {
101			var matches int
102			for pattern := range cfg.Models {
103				matched, err := filepath.Match(pattern, entry)
104				if err == nil && matched {
105					matches++
106				}
107			}
108			if matches == 0 {
109				return fmt.Errorf("warmup entry %q does not match any model pattern", entry)
110			}
111			if matches > 1 {
112				return fmt.Errorf("warmup entry %q matches %d model patterns (expected 1)", entry, matches)
113			}
114		}
115		if len(cfg.Warmup) > cfg.MaxModels {
116			return fmt.Errorf("warmup list length %d exceeds max_models %d", len(cfg.Warmup), cfg.MaxModels)
117		}
118		return nil
119	}
120	
